package ge.opensoft.openservice;

import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;

/** Bounded trusted-gateway assertions, executed with the mapped requester's current authority. */
final class InboundMail {
    private InboundMail() {}
    static String email(Object input){String value=WorkJobs.text(input,254).toLowerCase(Locale.ROOT);ContactFields.email(value);return value;}
    static Map<String,Object> mailbox(Store.Db db,String id)throws SQLException {var row=db.one("SELECT * FROM os_inbound_mailbox WHERE mailbox_id=?",id);if(row==null)throw new Failure(404,"Inbound mailbox not found");return row;}
    static Map<String,Object> gateway(Store.Db db,String id)throws SQLException {var user=db.one("SELECT * FROM os_user WHERE user_id=? AND active=1 AND api_only=1 AND role='agent' AND password_reset_required=0",id);if(user==null)throw new Failure(409,"Use an active API-only agent gateway without a pending password change");return user;}
    static Map<String,Object> adminPage(Store.Db db,String id)throws SQLException {
        Service.requireAccountAdministrator(db,db.viewerId);var selected=id.isEmpty()?map("mailbox_id","","address","","sender_domain","","gateway_id","","active",0,"revision",0):mailbox(db,id);var entries=new ArrayList<Map<String,Object>>();if(!id.isEmpty())for(var row:db.all("SELECT delivery_id,record_id,thread_id,created,mailbox_revision,sender_id FROM os_inbound_mail_receipt WHERE mailbox_id=? ORDER BY created DESC,delivery_id LIMIT 100",id)){String record=row.remove("record_id").toString(),sender=row.remove("sender_id").toString();Map<String,Object> item=map();try{item=FieldAccess.serialize(db,Service.readRecord(db,"sc_request",record));}catch(Failure hidden){ /* Retain delivery evidence without exposing an unavailable target. */ }row.put("record",item);row.put("sender",db.one("SELECT COALESCE((SELECT name FROM os_user WHERE user_id=?),'Removed account') AS name",sender).get("name"));entries.add(row);}return map("mailboxes",db.all("SELECT mailbox_id,address,sender_domain,active,revision FROM os_inbound_mailbox ORDER BY address"),"mailbox",selected,"gateway_name",selected.get("gateway_id").equals("")?"":db.one("SELECT COALESCE((SELECT name FROM os_user WHERE user_id=?),'Unavailable gateway') AS name",selected.get("gateway_id")).get("name"),"receipts",entries);
    }
    static Map<String,Object> configure(Store.Db db,String id,Object input)throws SQLException {
        Service.requireAccountAdministrator(db,db.viewerId);if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var body=object(input);require(body.keySet().equals(Set.of("revision","address","sender_domain","gateway_username","active")),"Provide the reviewed mailbox fields only");var old=id.isEmpty()?map("revision",0):mailbox(db,id);ProblemInvestigations.revision(body.get("revision"),old.get("revision"));require(body.get("active") instanceof Boolean,"Choose whether the mailbox is active");String address=email(body.get("address")),domain=WorkJobs.text(body.get("sender_domain"),253).toLowerCase(Locale.ROOT);ContactFields.email("mail@"+domain);String name=WorkJobs.text(body.get("gateway_username"),80);var account=db.one("SELECT user_id FROM os_user WHERE name=?",name);require(account!=null,"Choose an existing gateway account");String gateway=account.get("user_id").toString();if((Boolean)body.get("active"))gateway(db,gateway);if(db.one("SELECT mailbox_id FROM os_inbound_mailbox WHERE address=? AND mailbox_id<>?",address,id)!=null)throw new Failure(409,"This mailbox address is already configured");if(id.isEmpty()){require(db.count("SELECT COUNT(*) FROM os_inbound_mailbox")<100,"At most 100 inbound mailboxes are supported");id=Values.id();}int revision=((Number)old.get("revision")).intValue()+1;db.update("INSERT INTO os_inbound_mailbox(mailbox_id,address,sender_domain,gateway_id,active,revision) VALUES(?,?,?,?,?,?) ON CONFLICT(mailbox_id) DO UPDATE SET address=excluded.address,sender_domain=excluded.sender_domain,gateway_id=excluded.gateway_id,active=excluded.active,revision=excluded.revision",id,address,domain,gateway,(Boolean)body.get("active")?1:0,revision);SecurityEvents.record(db,db.viewerId,gateway,"mailbox.configured",map("mailbox_id",id,"revision",revision,"active",body.get("active")));return adminPage(db,id);
    }
    static Map<String,Object> request(Store.Db db,String id,boolean reply)throws SQLException {
        var item=Service.readRecord(db,"sc_request",id);var schema=Service.schema(db,"sc_request");for(String field:List.of("description","state"))if(!FieldAccess.allowed(db,schema,field))throw new Failure(403,"Mail intake requires request description and state access");if(reply){var rule=object(TypedFields.rules(schema).getOrDefault("description",map()));if(rule.containsKey("write_roles") && !((List<?>)rule.get("write_roles")).contains(db.viewerRole))throw new Failure(403,"Request comment write access required");if(!Set.of("open","fulfilling").contains(object(item.get("data")).get("state")))throw new Failure(409,"This request no longer accepts email follow-up");}return item;
    }
    static Map<String,Object> submit(Store.Db db,Map<String,Object> caller,String id,Object input)throws SQLException {
        if(!caller.containsKey("api_key_id"))throw new Failure(403,"Use the configured gateway's scoped API key");if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var mailbox=mailbox(db,id);if(((Number)mailbox.get("active")).intValue()!=1 || !caller.get("user_id").equals(mailbox.get("gateway_id")))throw new Failure(403,"Gateway is not enabled for this mailbox");gateway(db,caller.get("user_id").toString());var body=object(input);require(body.keySet().equals(Set.of("delivery_id","recipient","sender","sender_verified","subject","text","thread_id")),"Provide the gateway delivery fields only");require(Boolean.TRUE.equals(body.get("sender_verified")),"The trusted gateway must attest authenticated sender evidence");String delivery=WorkJobs.text(body.get("delivery_id"),160);require(delivery.matches("[A-Za-z0-9._:@/-]{1,160}"),"Use a bounded gateway delivery identifier");String recipient=email(body.get("recipient")),sender=email(body.get("sender"));require(recipient.equals(mailbox.get("address")),"Recipient does not match this mailbox");if(!sender.substring(sender.lastIndexOf('@')+1).equals(mailbox.get("sender_domain")))throw new Failure(403,"Sender domain is not allowed for this mailbox");var users=db.all("SELECT * FROM os_user WHERE LOWER(email)=? AND active=1 AND email_verified=1 AND role='requester' AND password_reset_required=0 AND api_only=0",sender);if(users.size()!=1)throw new Failure(403,"A unique current verified requester sender is required");var user=users.getFirst();String subject=WorkJobs.text(body.get("subject"),160),text=WorkJobs.text(body.get("text"),8000);Object supplied=body.get("thread_id");require(supplied instanceof String,"Provide a thread reference or an empty string");String thread=(String)supplied;require(thread.isEmpty() || thread.matches("[0-9a-f]{32}"),"Use the returned thread reference");String fingerprint=DigestUtils.sha256Hex(JSON.writeValueAsString(new TreeMap<>(body)));var receipt=db.one("SELECT * FROM os_inbound_mail_receipt WHERE mailbox_id=? AND delivery_id=?",id,delivery);String viewer=db.viewerId,role=db.viewerRole;
        try{
            db.viewerId=user.get("user_id").toString();db.viewerRole="requester";
            if(receipt!=null){if(!fingerprint.equals(receipt.get("fingerprint")) || !user.get("user_id").equals(receipt.get("sender_id")))throw new Failure(409,"Delivery identifier already represents different content or sender");var item=request(db,receipt.get("record_id").toString(),false);return map("record",FieldAccess.serialize(db,item),"thread_id",receipt.get("thread_id"),"duplicate",true);}
            require(db.count("SELECT COUNT(*) FROM os_inbound_mail_receipt WHERE mailbox_id=?",id)<10000,"Mailbox receipt capacity reached; operator review required");Map<String,Object> item;
            if(thread.isEmpty()){item=Requests.create(db,user.get("name").toString(),map("short_description",subject,"description",text));request(db,item.get("sys_id").toString(),false);thread=Values.id();db.update("INSERT INTO os_inbound_mail_thread(thread_id,mailbox_id,sender_id,record_id,created) VALUES(?,?,?,?,?)",thread,id,user.get("user_id"),item.get("sys_id"),now());}
            else{var target=db.one("SELECT record_id FROM os_inbound_mail_thread WHERE thread_id=? AND mailbox_id=? AND sender_id=?",thread,id,user.get("user_id"));if(target==null)throw new Failure(404,"Mail thread not found");require(db.count("SELECT COUNT(*) FROM os_inbound_mail_receipt WHERE thread_id=?",thread)<200,"Thread message capacity reached; use the request portal");item=request(db,target.get("record_id").toString(),true);Comments.add(db,item,map("body",text),user.get("name").toString());}
            db.update("INSERT INTO os_inbound_mail_receipt(mailbox_id,delivery_id,fingerprint,sender_id,record_id,thread_id,gateway_id,mailbox_revision,created) VALUES(?,?,?,?,?,?,?,?,?)",id,delivery,fingerprint,user.get("user_id"),item.get("sys_id"),thread,caller.get("user_id"),mailbox.get("revision"),now());Service.audit(db,item,user.get("name").toString(),"mail.received",map("mailbox_id",id,"thread_id",thread));return map("record",FieldAccess.serialize(db,item),"thread_id",thread,"duplicate",false);
        }finally{db.viewerId=viewer;db.viewerRole=role;}
    }
}
